"""Self-contained gfx1151 TileLang indexer for vLLM's DS4 sparse-attn logits.
Drop-in replacements for fp8_mqa_logits_torch / fp8_paged_mqa_logits_torch (next_n==1),
running the O(M*N) compute on a bf16 WMMA TileLang kernel instead of a Python loop.
Validated: prefill rel ~1.6e-3, decode rel ~1e-7 vs the torch fallbacks."""
import os, torch, tilelang, tilelang.language as T

_KCACHE = {}

# --- DS4_IDX_OFFICIAL=1: reproduce the official DeepSeek-V4 indexer QAT graph ---
# The official inference graph (HF snapshot inference/model.py Indexer.forward and
# Compressor.forward with rotate=True) applies, to BOTH indexer Q rows and indexer
# compressor K rows, after RoPE:
#     x -> hadamard128(x) / sqrt(128) -> fp4_act_quant(x, block=32, inplace)   (QAT sim)
# before the relu(q.k)*w scoring. ds4.c implements the same (dsv4_indexer_qat_*),
# and its comment warns the top-k selection "is not the model's graph" without it.
# vLLM's FP8 indexer path skips both steps. Because the fp8 storage scale is a
# power of two (exp2(ceil(log2(.)))), applying the transform HERE, to the
# dequantized-unscaled rows at score time, is exactly equivalent to applying it
# pre-quant (e2m1 grid + 2^ceil block scales shift covariantly), modulo the
# inherent fp8 storage rounding.
_IDX_OFFICIAL = os.environ.get("DS4_IDX_OFFICIAL", "0") == "1"
_H128 = {}
_FP4_LEVELS = {}
_FP4_MIDS = {}


def _hadamard128_matrix(device):
    h = _H128.get(device)
    if h is None:
        m = torch.ones(1, 1, dtype=torch.float32)
        base = torch.tensor([[1.0, 1.0], [1.0, -1.0]], dtype=torch.float32)
        for _ in range(7):
            m = torch.kron(base, m)
        h = (m * (128 ** -0.5)).to(device)
        _H128[device] = h
    return h


def _fp4_consts(device):
    lv = _FP4_LEVELS.get(device)
    if lv is None:
        lv = torch.tensor([0.0, 0.5, 1.0, 1.5, 2.0, 3.0, 4.0, 6.0], device=device)
        _FP4_LEVELS[device] = lv
        _FP4_MIDS[device] = torch.tensor(
            [0.25, 0.75, 1.25, 1.75, 2.5, 3.5, 5.0], device=device)
    return lv, _FP4_MIDS[device]


def _idx_qat(x):
    """hadamard128 + fp4(block=32, sat +-6, 2^ceil scale) round-trip on [..., 128]
    rows; returns bf16. Matches inference/kernel.py fp4_act_quant + ds4.c
    dsv4_indexer_qat_row_inplace_cpu."""
    shp = x.shape
    v = x.reshape(-1, 128).float() @ _hadamard128_matrix(x.device)
    v = v.view(-1, 4, 32)
    amax = v.abs().amax(-1, keepdim=True).clamp_min(6.0 * 2.0 ** -126)
    s = torch.exp2(torch.ceil(torch.log2(amax / 6.0)))
    y = (v / s).clamp(-6.0, 6.0)
    lv, mids = _fp4_consts(x.device)
    q = lv[torch.bucketize(y.abs(), mids)] * torch.sign(y)
    return (q * s).view(shp).to(torch.bfloat16)

# Granularity for bucketing the paged-indexer's seq_len_kv so its TileLang
# kernel is cached across decode steps instead of recompiling every token.
# Must be a multiple of the kernel's block_N (<=128) for the padded-K loop to
# stay in bounds; 512 -> at most one recompile per 512 generated tokens.
_KV_BUCKET = 512

# DS4_FUSE_IDXGATHER=1 (default): the decode gather+dequant+pad chain in
# fp8_paged_mqa_logits_tl runs as ONE fused triton kernel (ds4_fused_glue)
# instead of 5 aten kernels that stream the gathered cache bytes ~3x.
# Bit-exact (incl. the fp8 NaN encodings); =0 restores the aten chain.
_fused_glue = None
if os.environ.get("DS4_FUSE_IDXGATHER", "1") != "0":
    try:
        import ds4_fused_glue as _fused_glue
    except Exception:
        _fused_glue = None
_FUSE_IDXGATHER = _fused_glue is not None

def _build(seq_len, seq_len_kv, heads, index_dim, block_N=128, num_stages=2, threads=256, block_Q=None):
    if block_Q is None:
        block_Q = 1  # gfx1151: block_Q=1 + threads=256 validated correct at H=64,D=128
    dtype, accum, idt = "bfloat16", "float32", "int32"

    @T.prim_func
    def main(
        IndexQ: T.Tensor((seq_len * heads, index_dim), dtype),
        IndexK: T.Tensor((seq_len_kv, index_dim), dtype),
        IndexKScale: T.Tensor((seq_len_kv,), accum),
        Weights: T.Tensor((seq_len, heads), accum),
        CuSeqLenKS: T.Tensor((seq_len,), idt),
        CuSeqLenKE: T.Tensor((seq_len,), idt),
        Logits: T.Tensor((seq_len, seq_len_kv), accum),
    ):
        with T.Kernel(T.ceildiv(seq_len, block_Q), threads=threads) as bx:
            iq = T.alloc_shared([block_Q * heads, index_dim], dtype)
            ik = T.alloc_shared([block_N, index_dim], dtype)
            ksf = T.alloc_fragment([block_N], accum)
            s = T.alloc_fragment([block_N, block_Q * heads], accum)
            sr = T.reshape(s, (block_N, block_Q, heads))
            lg = T.alloc_fragment([block_N, block_Q], accum)
            w = T.alloc_fragment([block_Q, heads], accum)
            si = bx * block_Q
            kmin = T.alloc_var(idt); kmax = T.alloc_var(idt)
            kmin = 2147483647; kmax = -2147483648
            for b in T.serial(block_Q):
                kmin = T.min(kmin, T.min(CuSeqLenKS[si + b], seq_len_kv))
            for b in T.serial(block_Q):
                kmax = T.max(kmax, T.min(CuSeqLenKE[si + b], seq_len_kv))
            T.copy(IndexQ[si * heads, 0], iq)
            T.copy(Weights[si, 0], w)
            for nb in T.Pipelined(T.ceildiv(kmax - kmin, block_N), num_stages=num_stages):
                T.copy(IndexK[kmin + nb * block_N, 0], ik)
                T.copy(IndexKScale[kmin + nb * block_N], ksf)
                T.gemm(ik, iq, s, transpose_B=True, clear_accum=True, policy=T.GemmWarpPolicy.FullCol)
                for bn, bq, h in T.Parallel(block_N, block_Q, heads):
                    sr[bn, bq, h] = (T.max(sr[bn, bq, h], 0) * w[bq, h]) * ksf[bn]
                T.reduce_sum(sr, lg, dim=-1, clear=True)
                for bq, bn in T.Parallel(block_Q, block_N):
                    Logits[si + bq, kmin + nb * block_N + bn] = lg[bn, bq]
    return main


def _fit_config(block_Q, heads, D, budget=56 * 1024):
    """Pick (block_N, num_stages) so Q+K shared buffers fit gfx1151's 64KB LDS."""
    q_bytes = block_Q * heads * D * 2
    rem = budget - q_bytes
    for ns in (2, 1):
        for bn in (128, 64, 32, 16):
            if bn * D * 2 * ns <= rem:
                return bn, ns
    return 16, 1


def _kernel(seq_len, seq_len_kv, heads, index_dim, block_Q=1):
    block_N, num_stages = _fit_config(block_Q, heads, index_dim)
    key = (seq_len, seq_len_kv, heads, index_dim, block_Q, block_N, num_stages)
    if key not in _KCACHE:
        _KCACHE[key] = tilelang.compile(
            _build(seq_len, seq_len_kv, heads, index_dim, block_N=block_N,
                   num_stages=num_stages, threads=256, block_Q=block_Q), out_idx=[6])
    return _KCACHE[key]


# --- decode-specialized indexer kernel (query_len == 1) ------------------------
# The general _build grids over the QUERY length; at decode that is 1, so the
# whole KV scan runs in a single workgroup on one CU (~2 GB/s, ~40x under peak).
# For a single decode query, logit[j] = sum_h relu(q_h . k_j) * w_h * scale_j is
# independent across KV token j, so we instead grid over the KV dimension: one
# workgroup per block_N KV tokens -> full-GPU occupancy. Bit-exact vs _build
# (verified rel/abs err 0.0), ~47x faster at 64K (3.86ms -> 82us, ~105 GB/s).
_DKCACHE = {}
# block_N=64,threads=256: fastest CORRECT config on gfx1151 (~96 GB/s at 64K).
# threads MUST be 256 here: at 128 threads (2 warps) the block_N x heads(64)
# score tile is only partially computed -> WRONG logits (verified: threads=128
# gave max_abs_err ~3e2 vs 0.0 at 256; the sweep that favored 128 measured only
# speed). block_N>=256 overflows the 64KB LDS (block_N*D*2 for K alone hits 64KB).
_DEC_BLOCK_N = 64
_DEC_THREADS = 256


def _build_decode(seq_len_kv, heads, index_dim, block_N=_DEC_BLOCK_N, threads=_DEC_THREADS):
    dtype, accum = "bfloat16", "float32"

    @T.prim_func
    def main(
        IndexQ: T.Tensor((heads, index_dim), dtype),
        IndexK: T.Tensor((seq_len_kv, index_dim), dtype),
        IndexKScale: T.Tensor((seq_len_kv,), accum),
        Weights: T.Tensor((heads,), accum),
        Logits: T.Tensor((seq_len_kv,), accum),
    ):
        with T.Kernel(T.ceildiv(seq_len_kv, block_N), threads=threads) as bx:
            iq = T.alloc_shared([heads, index_dim], dtype)
            ik = T.alloc_shared([block_N, index_dim], dtype)
            ksf = T.alloc_fragment([block_N], accum)
            s = T.alloc_fragment([block_N, heads], accum)
            lg = T.alloc_fragment([block_N], accum)
            w = T.alloc_fragment([heads], accum)
            base = bx * block_N
            T.copy(IndexQ[0, 0], iq)
            T.copy(Weights[0], w)
            T.copy(IndexK[base, 0], ik)
            T.copy(IndexKScale[base], ksf)
            T.gemm(ik, iq, s, transpose_B=True, clear_accum=True,
                   policy=T.GemmWarpPolicy.FullCol)
            for bn, h in T.Parallel(block_N, heads):
                s[bn, h] = (T.max(s[bn, h], 0) * w[h]) * ksf[bn]
            T.reduce_sum(s, lg, dim=-1, clear=True)
            for bn in T.Parallel(block_N):
                Logits[base + bn] = lg[bn]
    return main


def _decode_kernel(seq_len_kv, heads, index_dim):
    # seq_len_kv is bucketed (multiple of _KV_BUCKET, itself a multiple of
    # _DEC_BLOCK_N) so the grid divides evenly and the kernel is reused across
    # decode steps (same cache-key discipline as _kernel).
    key = (seq_len_kv, heads, index_dim)
    if key not in _DKCACHE:
        _DKCACHE[key] = tilelang.compile(
            _build_decode(seq_len_kv, heads, index_dim), out_idx=[4])
    return _DKCACHE[key]


# --- multi-row decode kernel: K-stationary over the request's query rows ------
# Under the flatten path one request's speculative positions arrive as B rows
# with identical page lists (B=6, next_n=1 at spec=5). The gather is already
# shared per group, but the scorer above was launched once PER ROW, so the
# gathered bf16 K buffer (2 * ctx/compress_ratio * 128 bytes) streamed from
# DRAM six times per layer, 21 layers per step -- the dominant term that grows
# with context. Here a workgroup loads its block_N K tile ONCE and loops over
# the group's rows: Q (16 KB/row) is re-read per workgroup but stays L2/MALL
# resident, so DRAM traffic on K drops by the row count. Each row's causal
# bound is applied in the epilogue (columns >= KE[r] written as -inf), which
# also removes the per-row `logits[r, :ke] = lg[:ke]` slice copies.
#
# Bit-exact vs _build_decode: the per-row gemm tile (block_N x heads x D,
# FullCol policy), the relu*w*scale epilogue and the head reduction are the
# identical instruction sequence; only the outer row loop is new. Rows are
# padded to NR (zero Q, zero w, KE=0 -> all -inf) so NR is a compile-time
# constant and the kernel cache never sees a new row count mid-decode.
_DEC_NR = 6
_DMKCACHE = {}


def _build_decode_multi(seq_len_kv, heads, index_dim, n_rows,
                        block_N=_DEC_BLOCK_N, threads=_DEC_THREADS):
    dtype, accum, idt = "bfloat16", "float32", "int32"
    neg_inf = float("-inf")

    @T.prim_func
    def main(
        IndexQ: T.Tensor((n_rows * heads, index_dim), dtype),
        IndexK: T.Tensor((seq_len_kv, index_dim), dtype),
        IndexKScale: T.Tensor((seq_len_kv,), accum),
        Weights: T.Tensor((n_rows, heads), accum),
        KE: T.Tensor((n_rows,), idt),
        Logits: T.Tensor((n_rows, seq_len_kv), accum),
    ):
        with T.Kernel(T.ceildiv(seq_len_kv, block_N), threads=threads) as bx:
            iq = T.alloc_shared([heads, index_dim], dtype)
            ik = T.alloc_shared([block_N, index_dim], dtype)
            ksf = T.alloc_fragment([block_N], accum)
            s = T.alloc_fragment([block_N, heads], accum)
            lg = T.alloc_fragment([block_N], accum)
            w = T.alloc_fragment([heads], accum)
            base = bx * block_N
            T.copy(IndexK[base, 0], ik)
            T.copy(IndexKScale[base], ksf)
            for r in T.serial(n_rows):
                T.copy(IndexQ[r * heads, 0], iq)
                T.copy(Weights[r, 0], w)
                T.gemm(ik, iq, s, transpose_B=True, clear_accum=True,
                       policy=T.GemmWarpPolicy.FullCol)
                for bn, h in T.Parallel(block_N, heads):
                    s[bn, h] = (T.max(s[bn, h], 0) * w[h]) * ksf[bn]
                T.reduce_sum(s, lg, dim=-1, clear=True)
                for bn in T.Parallel(block_N):
                    Logits[r, base + bn] = T.if_then_else(
                        base + bn < KE[r], lg[bn], neg_inf)
    return main


def _decode_kernel_multi(seq_len_kv, heads, index_dim, n_rows):
    key = (seq_len_kv, heads, index_dim, n_rows)
    if key not in _DMKCACHE:
        _DMKCACHE[key] = tilelang.compile(
            _build_decode_multi(seq_len_kv, heads, index_dim, n_rows))
    return _DMKCACHE[key]


# DS4_IDX_HIP=1 (default): hand-HIP WMMA scorer (ds4_idx_score / libds4idx.so)
# reads the fp8 paged cache directly -- no gather, no bf16 copy, one launch per
# page-list group, logits written in place with the causal mask. Bit-exact vs
# the TileLang path (same WMMA k-steps, same butterfly head sum). =0 restores
# the gather + TileLang scorer. Falls back automatically when the library is
# missing or the shape is not (H=64, D=128, bs % 64 == 0, e4m3fn).
_hip_score = None
if os.environ.get("DS4_IDX_HIP", "1") != "0":
    try:
        import ds4_idx_score as _hip_score
        _hip_score._load()
    except Exception:
        _hip_score = None
_IDX_HIP = _hip_score is not None

# DS4_IDX_MULTIROW=1 (default): score all rows of a page-list group in one
# K-stationary launch. =0 restores the per-row scorer + slice copies.
_IDX_MULTIROW = os.environ.get("DS4_IDX_MULTIROW", "1") != "0"


# Bucket the PREFILL indexer's seq_len_kv so its TileLang kernel is reused across
# chunked-prefill steps. Chunked prefill feeds a growing context (seq_len_kv =
# 2048, 4096, ... per 2048-token chunk); without bucketing, _kernel's cache key
# (which includes seq_len_kv) misses EVERY chunk -> a ~2s hipcc recompile per chunk
# with the GPU idle (spiky 100%->30% util, slow long-prompt TTFT). The kernel bounds
# real work via CuSeqLenKE<=N (the KV loop runs ceildiv(kmax-kmin, block_N) with
# kmax=min(CuSeqLenKE, seq_len_kv)), so padding K/scale beyond N with zeros is inert
# and the padded logit columns are sliced off. 8192 -> <=8 distinct kernels up to 64K
# (was ~32) and they're one-time (cached in _KCACHE). Mirrors the decode-path fix.
_PREFILL_KV_BUCKET = 8192

def fp8_mqa_logits_tl(q, kv, weights, cu_seqlen_ks, cu_seqlen_ke):
    k_fp8, scale = kv
    M, H, D = q.shape
    N = k_fp8.shape[0]
    qb = q.to(torch.bfloat16).reshape(M * H, D).contiguous()
    kb = k_fp8.to(torch.bfloat16).contiguous()
    # NOTE: the indexer QAT rotation (Hadamard-128) is applied PRE-fp8-quant in
    # the fused q/compressor-K kernels (gated by DS4_IDX_OFFICIAL), not here — a
    # score-time rotation is a no-op for the dot product (H is orthonormal). See
    # ds4-vllm-indexer-qat-missing memory.
    scb = scale.reshape(-1).float().contiguous()
    Nb = ((N + _PREFILL_KV_BUCKET - 1) // _PREFILL_KV_BUCKET) * _PREFILL_KV_BUCKET
    if Nb != N:
        kb = F.pad(kb, (0, 0, 0, Nb - N))
        scb = F.pad(scb, (0, Nb - N))
    lg = _kernel(M, Nb, H, D)(qb, kb, scb,
                             weights.float().contiguous(),
                             cu_seqlen_ks.int().contiguous(), cu_seqlen_ke.int().contiguous())
    lg = lg[:, :N]
    idx = torch.arange(N, device=lg.device)[None, :]
    mask = (idx >= cu_seqlen_ks[:, None]) & (idx < cu_seqlen_ke[:, None])
    return lg.masked_fill(~mask, float("-inf"))


import torch.nn.functional as F
_BF16_WCACHE = {}
# Reuse an already-cached bf16 weight at prefill M as well as decode M. Set
# DS4_W8A8_BF16_PREFILL=0 to restrict the bf16 path to decode.
_BF16_PREFILL = os.environ.get("DS4_W8A8_BF16_PREFILL", "1") != "0"
def cached_bf16_weight(weight, weight_scale, block_size, m):
    """The bf16 dequantised copy of a block-scaled fp8 weight, or None.

    None means "do not take the bf16 path". That happens when the cache is cold
    and M is large: the startup memory-profiling forward runs at large M with an
    empty cache, and building the copy there inflates the measured footprint and
    shrinks the KV cache allocation. Decode (M <= 32) populates the cache;
    prefill reuses entries that already exist unless DS4_W8A8_BF16_PREFILL=0.
    """
    key = weight.data_ptr()
    wb = _BF16_WCACHE.get(key)
    if wb is not None:
        return wb if (m <= 32 or _BF16_PREFILL) else None
    if m > 32:
        return None
    bn, bk = block_size[0], block_size[1]
    N, K = weight.shape
    ws = weight_scale
    if ws.dtype == torch.float8_e8m0fnu:
        ws = ws.float()
    wf = weight.to(torch.float32).reshape(N // bn, bn, K // bk, bk)
    s = ws.to(torch.float32).reshape(N // bn, 1, K // bk, 1)
    wb = (wf * s).reshape(N, K).to(torch.bfloat16).contiguous()
    _BF16_WCACHE[key] = wb
    return wb


def w8a8_block_bf16_direct(x, weight, weight_scale, block_size, m):
    """Block-scaled fp8 linear WITHOUT the activation round-trip (DS4_W8A8_BF16_DIRECT).

    The caller of the stock path quantises its bf16 activation to fp8, and
    w8a8_block_fp8_bf16 below then dequantises it straight back to bf16 to reach
    this same GEMM. That round trip is pure cost -- 4 kernel launches and 2 real
    dtype conversions per call, ~255 calls per decode step -- and it is lossy.
    Given the caller's bf16 activation directly there is nothing to undo.

    Returns None when the bf16 weight is unavailable, meaning the caller must
    fall back to the stock fp8 path. Output is the raw GEMM result; the caller
    applies bias and the output dtype cast, matching the stock ordering.
    """
    wb = cached_bf16_weight(weight, weight_scale, block_size, m)
    if wb is None:
        return None
    from vllm.model_executor.layers.utils import rocm_unquantized_gemm_impl
    return rocm_unquantized_gemm_impl(x, wb)


def w8a8_block_fp8_bf16(qx, weight, x_scale, weight_scale, block_size, output_dtype):
    """gfx1151 fast path for block-scaled fp8 linear: dequant weight->bf16 (cached by
    storage ptr), dequant activation->bf16, then F.linear (rocBLAS/wvSplitK). ~24x faster
    than the untuned Triton block-scaled GEMM at M=1 decode."""
    M = qx.numel() // qx.shape[-1]
    wb = cached_bf16_weight(weight, weight_scale, block_size, M)
    if wb is None:
        from vllm.model_executor.layers.quantization.utils.fp8_utils import (
            w8a8_triton_block_scaled_mm)
        return w8a8_triton_block_scaled_mm(qx, weight, x_scale, weight_scale, block_size, output_dtype)
    bk = block_size[1]
    M, K = qx.shape
    xs = x_scale
    if xs.dtype == torch.float8_e8m0fnu:
        xs = xs.float()
    xf = qx.to(torch.float32).reshape(M, K // bk, bk)
    xb = (xf * xs.to(torch.float32).reshape(M, K // bk, 1)).reshape(M, K).to(torch.bfloat16)
    # Route through vLLM's ROCm GEMM dispatcher instead of F.linear: at decode
    # (M<=5) it selects the wvSplitK skinny-GEMM kernel, which is several times
    # faster than the hipblaslt MT16x16 tile path that aten::mm picks for M=1.
    # (Profiled 2026-07-12: aten::mm via Cijk_*MT16x16 = ~22% of decode GPU time.)
    from vllm.model_executor.layers.utils import rocm_unquantized_gemm_impl
    return rocm_unquantized_gemm_impl(xb, wb).to(output_dtype)


# Cross-layer memo for the row->group map. The flatten path turns one request's
# next_n speculative positions into next_n separate rows (B=6, next_n=1 at
# spec=5), each with its OWN block_tables row -- but those rows are identical,
# because they are the same request. Without grouping, every row re-gathers and
# re-dequantises that request's entire compressed-K cache: 6x per layer, 21
# layers per step. Only the causal bound ke differs between them.
#
# Sharing is exact, not approximate: column c of the logits depends only on
# k[c], so computing extra columns beyond a row's own ke cannot perturb the
# columns it keeps. Gathering at the group's longest context and letting each
# row apply its own ke is therefore bit-identical to gathering per row.
#
# The device compare needs one D2H, so it is memoised on the block_tables
# storage pointer -- once per step rather than once per indexer layer.
_BT_GROUP_MEMO = {}


def _row_groups(block_tables, npgs):
    """rep[i] = representative row index for row i (rows sharing a page list)."""
    key = (block_tables.data_ptr(), int(block_tables.shape[0]))
    g = _BT_GROUP_MEMO.get(key)
    if g is not None:
        return g
    B = int(block_tables.shape[0])
    bt = block_tables[:, :max(npgs)].tolist() if B else []
    rep_ = list(range(B))
    for i in range(1, B):
        for j in range(i):
            m = min(npgs[i], npgs[j])
            if m > 0 and bt[i][:m] == bt[j][:m]:
                rep_[i] = rep_[j]
                break
    _BT_GROUP_MEMO.clear()
    _BT_GROUP_MEMO[key] = rep_
    return rep_


# Cross-layer memo for the host copy of context_lens: all indexer layers in a
# decode step receive the SAME seq_lens tensor object from the shared metadata
# builder, so one D2H sync serves the whole step instead of one per layer (each
# .item()/.tolist() drains the async GPU queue -> ~40+ pipeline stalls/step).
# Holding a strong ref to the tensor makes the `is` identity check sound (the
# object cannot be freed and its id reused while we hold it); an in-place write
# would bump _version, which we also check.
_CLS_LAST = None
_CLS_VER = None
_CLS_HOST = None
_SHAPES_SEEN = set()


def _context_lens_host(context_lens):
    """Host copy of seq_lens, memoised across the step's 21 indexer layers.

    The caller MUST pass the tensor it received from the metadata builder, not a
    view of it. Squeezing/reshaping first mints a fresh Python object on every
    call, the `is` check never hits, and the memo silently degrades to one
    blocking .tolist() per layer -- 21 pipeline stalls per decode step instead
    of 1. That is exactly what happened until 2026-08-07: the caller did
    `context_lens = context_lens.squeeze(-1)` before calling in, and the sync
    tracer caught it at 21.0 events/step. The reshape now lives in here, after
    the identity check, so the key stays the caller's stable object.
    """
    global _CLS_LAST, _CLS_VER, _CLS_HOST
    if context_lens is _CLS_LAST and context_lens._version == _CLS_VER:
        return _CLS_HOST
    host = (context_lens.reshape(-1) if context_lens.dim() > 1
            else context_lens).tolist()
    _CLS_LAST, _CLS_VER, _CLS_HOST = context_lens, context_lens._version, host
    return host


def fp8_paged_mqa_logits_tl(q, kv_cache, weights, context_lens, block_tables, max_model_len):
    from vllm.utils.math_utils import cdiv
    from vllm.platforms import current_platform
    fp8 = current_platform.fp8_dtype()
    B, next_n, H, dim = q.size()
    bs = kv_cache.shape[1]
    # Pass the builder's tensor straight through: see _context_lens_host on why
    # squeezing here defeats the cross-layer memo.
    cls = _context_lens_host(context_lens)
    if (B, next_n) not in _SHAPES_SEEN:
        _SHAPES_SEEN.add((B, next_n))
        print(f"[ds4_tl_indexer] paged-decode shape B={B} next_n={next_n} "
              f"ctx[:4]={cls[:4]}", flush=True)
    flat = kv_cache.view(-1, bs * (dim + 4))
    so = bs * dim
    rows = B * next_n
    qb = q.to(torch.bfloat16)
    # (Indexer QAT rotation is pre-fp8-quant in the fused kernels, not here.)
    # Narrow bucketed logits buffer instead of [rows, max_model_len]:
    # top_k_per_row_decode addresses the buffer via the strides we hand it and
    # never reads a column >= its per-row causal bound (ke <= sl <= slk), so
    # the 256K-wide -inf fill per layer-call was pure overhead. Columns beyond
    # each row's ke stay -inf from this fill, mirroring the reference masking.
    slks = [((sl + _KV_BUCKET - 1) // _KV_BUCKET) * _KV_BUCKET for sl in cls]
    width = max(max(slks), _KV_BUCKET)
    logits = torch.full([rows, width], float("-inf"), device=q.device, dtype=torch.float32)
    # Group rows that share a page list: under the flatten path those are one
    # request's speculative positions, and each was re-gathering the same cache.
    npgs = [cdiv(sl, bs) if sl else 0 for sl in cls]
    rep = _row_groups(block_tables, npgs) if B > 1 else [0]
    gmax = {}
    for i in range(B):
        if cls[i] == 0:
            continue
        g = rep[i]
        if g not in gmax or cls[i] > gmax[g][0]:
            gmax[g] = (cls[i], slks[i], i)
    gcache = {}
    gdone = set()

    for i in range(B):
        sl = cls[i]
        if sl == 0:
            continue
        if (_IDX_HIP and next_n == 1 and fp8 is torch.float8_e4m3fn
                and _hip_score.eligible(H, dim, bs, fp8)):
            # HIP WMMA scorer straight from the paged cache: no gather at all.
            if rep[i] in gdone:
                continue
            gdone.add(rep[i])
            members = [m for m in range(B) if rep[m] == rep[i] and cls[m] > 0]
            gsl, gslk, gi = gmax[rep[i]]
            npg = cdiv(gsl, bs)
            ntiles = gslk // 64
            bt_row = block_tables[gi]
            if bt_row.dtype != torch.int32 or not bt_row.is_contiguous():
                bt_row = bt_row.to(torch.int32).contiguous()
            cl_gpu = context_lens.reshape(-1)
            m0 = 0
            while m0 < len(members):
                chunk = members[m0:m0 + 64]
                m0 += 64
                nr = len(chunk)
                contig = chunk == list(range(chunk[0], chunk[0] + nr))
                if contig:
                    q_rows = qb[chunk[0]:chunk[0] + nr, 0].reshape(nr * H, dim)
                    w_rows = weights[chunk[0]:chunk[0] + nr]
                    ke_rows = cl_gpu[chunk[0]:chunk[0] + nr]
                else:
                    q_rows = qb[chunk, 0].reshape(nr * H, dim)
                    w_rows = weights[chunk]
                    ke_rows = cl_gpu[chunk]
                if not q_rows.is_contiguous():
                    q_rows = q_rows.contiguous()
                w_rows = w_rows.float()
                if not w_rows.is_contiguous():
                    w_rows = w_rows.contiguous()
                ke_rows = ke_rows.to(torch.int32)
                if not ke_rows.is_contiguous():
                    ke_rows = ke_rows.contiguous()
                if contig:
                    # in place: rows chunk[0]..chunk[0]+nr-1 of the shared
                    # logits buffer (row stride = width, columns contiguous)
                    out = logits[chunk[0]:chunk[0] + nr]
                    _hip_score.score(flat, bt_row, npg, bs, q_rows, w_rows, ke_rows, out, ntiles)
                else:
                    tmp = torch.empty((nr, gslk), dtype=torch.float32, device=q.device)
                    _hip_score.score(flat, bt_row, npg, bs, q_rows, w_rows, ke_rows, tmp, ntiles)
                    logits[chunk, :gslk] = tmp
            continue
        got = gcache.get(rep[i])
        if got is None:
            # Gather+dequant ONCE per group, at the group's longest context.
            # Sharing is exact: logits column c depends only on k[c], so the
            # surplus columns a shorter row does not keep cannot perturb the
            # ones it does. Each row still applies its own causal bound ke.
            gsl, gslk, gi = gmax[rep[i]]
            npg = cdiv(gsl, bs); psl = npg * bs
            # (Indexer QAT rotation is pre-fp8-quant in the compressor store
            # kernel.) Bucket seq_len_kv coarsely so the TileLang kernel is
            # reused across decode steps: without it sl grows by 1 every token,
            # the _decode_kernel() cache misses every step and TileLang re-runs
            # hipcc mid-decode -- a hard throughput cliff (16->1.5 tok/s). The
            # kernel bounds its real work at runtime, so padding K/scale beyond
            # sl with zeros is inert (padded logit columns stay masked below).
            if _FUSE_IDXGATHER and fp8 is torch.float8_e4m3fn:
                # Fused gather+dequant+pad: ONE triton kernel reads the paged
                # cache once and writes the padded bf16 K / fp32 scale buffers
                # directly (bit-exact vs the aten chain below, incl. the fp8
                # NaN encodings; DS4_FUSE_IDXGATHER=0 restores the chain).
                cv, cs = _fused_glue.gather_dequant_pad(
                    flat, block_tables[gi], npg, gsl, gslk, bs, dim, False)
            else:
                cache = flat[block_tables[gi, :npg]]
                cv = cache[..., :so].view(dtype=fp8).to(torch.bfloat16).view(psl, dim)[:gsl].contiguous()
                cs = cache[..., so:].view(dtype=torch.float32).contiguous().view(psl)[:gsl].contiguous()
                if gslk != gsl:
                    cv = F.pad(cv, (0, 0, 0, gslk - gsl))
                    cs = F.pad(cs, (0, gslk - gsl))
            got = (cv, cs, gslk)
            gcache[rep[i]] = got
        cv, cs, slk = got
        if _IDX_MULTIROW and next_n == 1:
            # Whole group in one K-stationary launch (see _build_decode_multi).
            # Rows are collected the first time their group is seen; later
            # rows of the same group were scored in that launch.
            if rep[i] in gdone:
                continue
            members = [m for m in range(B) if rep[m] == rep[i] and cls[m] > 0]
            gdone.add(rep[i])
            kern = _decode_kernel_multi(slk, H, dim, _DEC_NR)
            for m0 in range(0, len(members), _DEC_NR):
                chunk = members[m0:m0 + _DEC_NR]
                nr = len(chunk)
                contig = chunk == list(range(chunk[0], chunk[0] + nr))
                # Per-row causal bound is the row's own context length (every
                # member's cls <= the group's gsl <= its bucket slk), taken from
                # the builder's GPU tensor: no host->device copy per layer.
                cl_gpu = context_lens.reshape(-1)
                if nr == _DEC_NR and contig:
                    q_rows = qb[chunk[0]:chunk[0] + nr, 0].reshape(nr * H, dim)
                    w_rows = weights[chunk[0]:chunk[0] + nr]
                    ke_rows = cl_gpu[chunk[0]:chunk[0] + nr]
                else:
                    q_rows = torch.zeros((_DEC_NR, H, dim), dtype=torch.bfloat16, device=q.device)
                    w_rows = torch.zeros((_DEC_NR, H), dtype=torch.float32, device=q.device)
                    ke_rows = torch.zeros((_DEC_NR,), dtype=torch.int32, device=q.device)
                    q_rows[:nr] = qb[chunk, 0]
                    w_rows[:nr] = weights[chunk]
                    ke_rows[:nr] = cl_gpu[chunk]
                    q_rows = q_rows.reshape(_DEC_NR * H, dim)
                if not q_rows.is_contiguous():
                    q_rows = q_rows.contiguous()
                w_rows = w_rows.float()
                if not w_rows.is_contiguous():
                    w_rows = w_rows.contiguous()
                ke_rows = ke_rows.to(torch.int32)
                if not ke_rows.is_contiguous():
                    ke_rows = ke_rows.contiguous()
                # Single-group, full-width batch (one decoding request, the
                # common case): the kernel writes the final logits rows in
                # place -- no slice copies at all. Otherwise score into a
                # group-sized buffer and copy the bucket width once.
                direct = (nr == _DEC_NR and contig and chunk[0] == 0
                          and rows == _DEC_NR and width == slk)
                out = logits if direct else torch.empty(
                    (_DEC_NR, slk), dtype=torch.float32, device=q.device)
                kern(q_rows, cv, cs, w_rows, ke_rows, out)
                if not direct:
                    logits[chunk, :slk] = out[:nr]
            continue
        # KV-gridded decode kernel: ~47x faster than the per-query _kernel at
        # long context (grid over KV tokens instead of query_len=1). slk is a
        # multiple of _KV_BUCKET (a multiple of _DEC_BLOCK_N) so the grid
        # divides evenly.
        kern = _decode_kernel(slk, H, dim)
        for j in range(next_n):
            r = i * next_n + j
            lg = kern(
                qb[i, j].reshape(H, dim).contiguous(), cv, cs,
                weights[r].float().reshape(H).contiguous())
            # Per-row causal bound: with speculative verify (next_n > 1), query
            # row j may only see keys k < ke = sl - next_n + j + 1 (matches the
            # reference q_offsets masking; for next_n == 1 this is ke = sl).
            ke = sl - next_n + j + 1
            if ke > 0:
                logits[r, :ke] = lg[:ke]
    # --- diagnostic: rank of a target compressed row among valid logits ---
    if os.environ.get("DS4_DBG_NEEDLE") and B == 1:
        nrow = int(os.environ["DS4_DBG_NEEDLE"])
        sl0 = cls[0]
        if sl0 > 5000 and 0 <= nrow < sl0:
            global _DBG_N
            try: _DBG_N
            except NameError: _DBG_N = 0
            if _DBG_N < 24:
                _DBG_N += 1
                col = logits[0, :sl0]
                topk = int(os.environ.get("DS4_DBG_TOPK", "512"))
                lo, hi = max(0, nrow - 6), min(sl0, nrow + 7)
                best_rank, best_row = sl0, -1
                for rr in range(lo, hi):
                    v = col[rr].item()
                    rk = int((col > v).sum().item())
                    if rk < best_rank:
                        best_rank, best_row = rk, rr
                print(f"[DS4_DBG] needle rows[{lo},{hi}) best_row={best_row} "
                      f"best_rank={best_rank}/{sl0} "
                      f"selected={'YES' if best_rank < topk else 'NO'} "
                      f"(call {_DBG_N})", flush=True)
    return logits
